mapper.select:
SELECT id, conversation_id, type, name, avatar_url, created_by,
       last_message_id, last_message_at, created_at, updated_at, deleted_at, delete_flag
FROM conversations
WHERE conversation_id = #{conversationId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.update:
UPDATE conversations
SET name = #{conversation.name},
    avatar_url = #{conversation.avatarUrl},
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.select:
SELECT c.id, c.conversation_id, c.type, c.name, c.avatar_url, c.created_by,
       c.last_message_id, c.last_message_at, c.created_at, c.updated_at, c.deleted_at, c.delete_flag
FROM conversations c
INNER JOIN conversation_participants cp ON c.conversation_id = cp.conversation_id
WHERE cp.employee_id = #{employeeId}
  AND cp.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND c.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
ORDER BY c.last_message_at DESC NULLS LAST, c.created_at DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(DISTINCT c.id)
FROM conversations c
INNER JOIN conversation_participants cp ON c.conversation_id = cp.conversation_id
WHERE cp.employee_id = #{employeeId}
  AND cp.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND c.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.update:
UPDATE conversations
SET last_message_id = #{lastMessageId},
    last_message_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.select:
SELECT c.id, c.conversation_id, c.type, c.name, c.avatar_url, c.created_by,
       c.last_message_id, c.last_message_at, c.created_at, c.updated_at, c.deleted_at, c.delete_flag
FROM conversations c
INNER JOIN conversation_participants cp1 ON c.conversation_id = cp1.conversation_id
INNER JOIN conversation_participants cp2 ON c.conversation_id = cp2.conversation_id
WHERE c.type = 'DIRECT'
  AND c.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND cp1.employee_id = #{employeeId1}
  AND cp1.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND cp2.employee_id = #{employeeId2}
  AND cp2.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
LIMIT 1

SELECT c.id, c.conversation_id, c.type, c.name, c.avatar_url, c.created_by,
       c.last_message_id, c.last_message_at, c.created_at, c.updated_at, c.deleted_at, c.delete_flag
FROM conversations c
INNER JOIN conversation_participants cp ON c.conversation_id = cp.conversation_id
WHERE cp.employee_id = #{employeeId}
  AND cp.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND c.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}


    AND (
        COALESCE(c.last_message_at, c.created_at) < #{lastMessageAt}
        OR (COALESCE(c.last_message_at, c.created_at) = #{lastMessageAt} AND c.id < #{lastId})
    )


ORDER BY COALESCE(c.last_message_at, c.created_at) DESC, c.id DESC
LIMIT #{limit}
